    for omit_tools_from in [
        &["code_mode"][..],
        &["deferred"][..],
        &["direct"][..],
        &["code_mode", "deferred"][..],
        &["code_mode", "direct"][..],
        &["deferred", "direct"][..],
        &["code_mode", "deferred", "direct"][..],
        &[][..],
    ] {
        for (code_mode_only, supports_search_tool, non_prefixed_mcp_tool_names) in [
            (false, false, false),
            (false, false, true),
            (false, true, false),
            (false, true, true),
            (true, false, false),
            (true, false, true),
            (true, true, false),
            (true, true, true),
