    let phase_3_wait = wait_for_file_source(&phase_3_gate)?;

    let code = format!(
        r#"
text("phase 1");
yield_control();
{phase_2_wait}
text((await tools.exec_command({{cmd: "printf 'phase 2'"}})).output);
{phase_3_wait}
text((await tools.exec_command({{cmd: "printf 'phase 3'"}})).output);
"#
    );

    responses::mount_sse_once(
        &server,
        sse(vec![
