fn list_skills(
        &self,
        mut query: SkillListQuery,
        thread_state: &SkillsThreadState,
    ) -> SkillCatalog {
        let include_cloud_skills = query.include_cloud_skills;
        query.include_cloud_skills = false;

        let mut catalog = self.providers.list_for_turn(query).await;
