pub fn message_board_tools(
    board: Arc<dyn AgentMessageBoard>,
    caller: ThreadId,
    caller_path: AgentPath,
    namespace: Option<&str>,
    namespace_description: &str,
) -> Vec<Arc<dyn for<'call> ToolExecutor<ToolCall<'call>>>> {
