E00579.text:
pub(crate) fn message_board_tools_with_descriptions(
    board: Arc<dyn AgentMessageBoard>,
    caller: ThreadId,
    caller_path: AgentPath,
    namespace: Option<&str>,
    namespace_description: &str,
    tool_messages: Option<&MultiAgentToolMessages>,
) -> Vec<Arc<dyn for<'call> ToolExecutor<ToolCall<'call>>>> {
    spec::NAMES
        .into_iter()
        .map(|name| {
            let tool_message = tool_messages.and_then(|tools| tools.by_name(name));
            if tool_message.is_some_and(|tool| tool.parameters.is_some()) {
                tracing::warn!(
                    tool = name,
                    "Channel tool parameters cannot be overridden; using bundled parameters"
                );
            }
            Arc::new(BoardTool {
                board: board.clone(),
                caller,
                caller_path: caller_path.clone(),
                name,
                namespace: namespace.map(str::to_owned),
                namespace_description: namespace_description.to_owned(),
                description: tool_message.and_then(|tool| tool.description.clone()),
            }) as Arc<dyn for<'call> ToolExecutor<ToolCall<'call>>>
        })
        .collect()
}

E00580.text:
fn execute(
        &self,
        raw: &str,
        call: &ToolCall<'_>,
        budget: usize,
    ) -> Result<Value, BoardToolError> {
        let board = &self.board;
        let caller = self.caller;
        let page_limit = |limit: Option<NonZeroU32>| limit.map_or(20, NonZeroU32::get).min(50);
        let preview_limit =
            |limit: Option<NonZeroU32>| limit.map_or(1000, NonZeroU32::get).min(20_000);
        let page = |limit, cursor, scale| PageRequest {
            limit: nonzero(limit / scale),
            cursor,
        };
        let direction = |recent_first: Option<bool>| {
            if recent_first.unwrap_or(true) {
                SortDirection::NewestFirst
            } else {
                SortDirection::OldestFirst
            }
        };
        match self.name {
            "create_channel" => {
                let arguments::CreateChannel {
                    channel_name,
                    description,
                    subscribe,
                } = serde_json::from_str(raw).map_err(model_error)?;
                // JSON can escape each description byte into six output bytes.
                let description_budget = description
                    .as_ref()
                    .map_or(0, |text| text.as_str().len() * 6);
                self.check_mutation_budget(
                    budget.saturating_sub(description_budget),
                    /*target_path_bytes*/ 0,
                )?;
                encode(
                    board
                        .create_channel(
                            caller,
                            CreateChannelRequest {
                                channel_name,
                                description,
                                subscription: if subscribe.unwrap_or(true) {
                                    SubscriptionChange::Subscribe
                                } else {
                                    SubscriptionChange::Unsubscribe
                                },
                            },
                        )
                        .await,
                )
            }
            "get_channels" => {
                let arguments::GetChannels {
                    query,
                    recent_first,
                    limit,
                    cursor,
                } = serde_json::from_str(raw).map_err(model_error)?;
                let limit = page_limit(limit);
                bounded_read(budget, limit, |scale| {
                    board.list_channels(
                        caller,
                        ChannelQuery {
                            query: query.clone(),
                            direction: direction(recent_first),
                            page: page(limit, cursor.clone(), scale),
                        },
                    )
                })
                .await
            }
            "list_threads" => {
                let arguments::ListThreads {
                    channel_name,
                    sort,
                    recent_first,
                    limit,
                    cursor,
                    max_chars_per_post,
                } = serde_json::from_str(raw).map_err(model_error)?;
                let limit = page_limit(limit);
                let max_chars_per_post = preview_limit(max_chars_per_post);
                bounded_read(budget, limit.max(max_chars_per_post), |scale| {
                    board.list_threads(
                        caller,
                        ThreadQuery {
                            channel_name: channel_name.clone(),
                            sort: sort.unwrap_or(ThreadSort::Created),
                            direction: direction(recent_first),
                            max_chars_per_post: nonzero(max_chars_per_post / scale),
                            page: page(limit, cursor.clone(), scale),
                        },
                    )
                })
                .await
            }
            "search_posts" => {
                let arguments::SearchPosts {
                    channel_name,
                    query,
                    after_message_id,
                    author,
                    limit,
                    cursor,
                    max_chars_per_post,
                } = serde_json::from_str(raw).map_err(model_error)?;
                let author = author
                    .map(|path| self.caller_path.resolve(&path))
                    .transpose()
                    .map_err(model_error)?;
                let limit = page_limit(limit);
                let max_chars_per_post = preview_limit(max_chars_per_post);
                bounded_read(budget, limit.max(max_chars_per_post), |scale| {
                    board.search_posts(
                        caller,
                        PostQuery {
                            channel_name: channel_name.clone(),
                            query: query.clone(),
                            after_message_id,
                            author: author.clone(),
                            max_chars_per_post: nonzero(max_chars_per_post / scale),
                            page: page(limit, cursor.clone(), scale),
                        },
                    )
                })
                .await
            }
            "read_thread" => {
                let arguments::ReadThread {
                    thread_id,
                    limit,
                    cursor,
                    max_chars_per_post,
                } = serde_json::from_str(raw).map_err(model_error)?;
                let limit = page_limit(limit);
                let max_chars_per_post = preview_limit(max_chars_per_post);
                bounded_read(budget, limit.max(max_chars_per_post), |scale| {
                    board.read_thread(
                        caller,
                        ReadThreadRequest {
                            thread_id,
                            max_chars_per_post: nonzero(max_chars_per_post / scale),
                            page: page(limit, cursor.clone(), scale),
                        },
                    )
                })
                .await
            }
            "read_post" => {
                let arguments::ReadPost {
                    message_id,
                    offset_chars,
                    limit_chars,
                } = serde_json::from_str(raw).map_err(model_error)?;
                let limit_chars = limit_chars.map_or(20_000, NonZeroU32::get).min(20_000);
                bounded_read(budget, limit_chars, |scale| {
                    board.read_post(
                        caller,
                        ReadPostRequest {
                            message_id,
                            offset_chars: offset_chars.unwrap_or_default(),
                            limit_chars: nonzero(limit_chars / scale),
                        },
                    )
                })
                .await
            }
            "subscribe" | "unsubscribe" => {
                let arguments::Subscription {
                    channel_name,
                    thread_id,
                    target_agent,
                } = serde_json::from_str(raw).map_err(model_error)?;
                self.check_mutation_budget(budget, target_agent.as_ref().map_or(0, String::len))?;
                let target = match (channel_name, thread_id) {
                    (Some(channel), None) => SubscriptionTarget::Channel(channel),
                    (None, Some(thread)) => SubscriptionTarget::Thread(thread),
                    _ => {
                        return Err(
                            model_error("Supply exactly one of channel_name or thread_id").into(),
                        );
                    }
                };
                encode(
                    board
                        .set_subscription(
                            caller,
                            SubscriptionRequest {
                                target,
                                target_agent: target_agent
                                    .map(|path| self.caller_path.resolve(&path))
                                    .transpose()
                                    .map_err(model_error)?,
                                change: if self.name == "subscribe" {
                                    SubscriptionChange::Subscribe
                                } else {
                                    SubscriptionChange::Unsubscribe
                                },
                            },
                        )
                        .await,
                )
            }
            "post" => {
                let arguments::Post {
                    text,
                    channel_name,
                    new_channel_name,
                    thread_id,
                    agents_to_notify,
                } = serde_json::from_str(raw).map_err(model_error)?;
                self.check_mutation_budget(budget, /*target_path_bytes*/ 0)?;
                let destination = match (channel_name, new_channel_name, thread_id) {
                    (Some(channel), None, None) => PostDestination::Channel(channel),
                    (None, Some(channel), None) => PostDestination::NewChannel(channel),
                    (None, None, Some(thread)) => PostDestination::Thread(thread),
                    _ => {
                        return Err(model_error(
                            "Supply exactly one of channel_name, new_channel_name or thread_id",
                        )
                        .into());
                    }
                };
                let invocation = match &call.source {
                    ToolCallSource::Direct => call.call_id.clone(),
                    ToolCallSource::CodeMode {
                        cell_id,
                        runtime_tool_call_id,
                    } => format!("{cell_id}:{runtime_tool_call_id}"),
                };
                encode(
                    board
                        .post(
                            caller,
                            PostRequest {
                                request_id: format!("{}:{invocation}", call.turn_id),
                                destination,
                                text,
                                agents_to_notify: agents_to_notify
                                    .unwrap_or_default()
                                    .into_iter()
                                    .map(|path| self.caller_path.resolve(&path))
                                    .collect::<Result<_, _>>()
                                    .map_err(model_error)?,
                            },
                        )
                        .await,
                )
            }
            _ => unreachable!("only registered message-board tools can be called"),
        }
    }

E00581.text:
fn check_mutation_budget(
    &self,
    budget: usize,
    target_path_bytes: usize,
) -> Result<(), FunctionCallError> {
    // Reserve metadata, escaped channel names and agent paths before any write.
    if budget < 2048 + self.caller_path.len() + target_path_bytes {
        return Err(model_error(
            "Output budget is too small to acknowledge a message-board mutation; no change was made.",
        ));
    }
    Ok(())
}

E00582.text:
fn bounded_read<'a, T: Serialize>(
    budget: usize,
    largest_limit: u32,
    fetch: impl Fn(u32) -> BoxFuture<'a, codex_protocol::error::Result<T>>,
) -> Result<Value, BoardToolError> {
    let mut scale = 1;
    loop {
        let result = encode(fetch(scale).await)?;
        if result.to_string().len() <= budget {
            return Ok(result);
        }
        if largest_limit / scale <= 1 {
            break;
        }
        scale *= 2;
    }
    Err(model_error("The output budget is too small for this result's metadata.").into())
}

E00586.text:
fn encode<T: Serialize>(value: codex_protocol::error::Result<T>) -> Result<Value, BoardToolError> {
    let value = value.map_err(|error| {
        if let CodexErrorDetails::Io(io) = error.details()
            && let Some(denied) = io
                .get_ref()
                .and_then(|source| source.downcast_ref::<PermissionDenied>())
        {
            BoardToolError::PermissionDenied(denied.clone())
        } else {
            BoardToolError::Model(model_error(error))
        }
    })?;
    serde_json::to_value(value).map_err(|error| model_error(error).into())
}

E00588.text:
fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    write!(f, "permission_denied: {}", self.message)
}

E00589.text:
fn from(error: PermissionDenied) -> Self {
    Self::Io(std::io::Error::new(
        std::io::ErrorKind::PermissionDenied,
        error,
    ))
}

E00590.text:
pub(crate) fn model_response(&self, budget: usize) -> Result<Value, FunctionCallError> {
    // Keep the denial structured and below 1k tokens, even for oversized service text.
    let mut limit = 512;
    loop {
        let truncated = std::iter::once(self.message.as_str())
            .chain(self.action.as_deref())
            .chain(self.resource.as_deref())
            .any(|text| text.chars().count() > limit);
        let mut result = json!({"error": Self {
            message: self.message.chars().take(limit).collect(),
            action: self.action.as_ref().map(|text| text.chars().take(limit).collect()),
            resource: self.resource.as_ref().map(|text| text.chars().take(limit).collect()),
        }});
        if truncated {
            result["error"]["truncated"] = json!(true);
        }
        if result.to_string().len() <= budget.min(/*other*/ 768) {
            return Ok(result);
        }
        if limit == 0 {
            return Err(FunctionCallError::RespondToModel(
                "permission_denied: output budget too small for the error".into(),
            ));
        }
        limit /= 2;
    }
}

