fn loader_overrides_for_profile(
    profile_v2: Option<&ProfileV2Name>,
) -> anyhow::Result<LoaderOverrides> {
    match profile_v2 {
        Some(profile_v2) => {
            let codex_home = find_codex_home()?;
            Ok(loader_overrides_for_profile_at_codex_home(
                Some(profile_v2),
                &codex_home,
            ))
        }
        None => Ok(LoaderOverrides::default()),
